CREATE OR REPLACE FUNCTION f_gap_fill_update(tbl text, id text, row_num text) RETURNS void LANGUAGE plpgsql AS $func$
DECLARE
    col text;
    cols_to_fill text[];
    update_sql text;
    set_clause text;
    join_condition text;
    window_def text;
BEGIN
    -- Get list of nullable columns, excluding the id and row_num columns
    SELECT array_agg(column_name)
    INTO cols_to_fill
    FROM information_schema.columns
    WHERE table_name = tbl
      AND is_nullable = 'YES'
      AND column_name != id
      AND column_name != row_num;

    -- If no columns to fill, exit
    IF cols_to_fill IS NULL OR array_length(cols_to_fill, 1) = 0 THEN
        RETURN;
    END IF;

    -- Build the window definition
    window_def := 'PARTITION BY ' || quote_ident(id) || ' ORDER BY ' || quote_ident(row_num);

    -- Build the SET clause and the CTE columns
    set_clause := '';
    join_condition := '';

    -- We need to generate a CTE that calculates the filled values for all columns at once
    -- Then join back to update.

    -- Construct the SELECT part of the CTE
    -- We select the id, row_num, and the filled version of each column
    -- Format: id, row_num, LAST_VALUE(col IGNORE NULLS) OVER (...) as col_filled

    -- Let's build the CTE query string
    -- CTE name: filled_data
    -- Columns: id, row_num, col1_filled, col2_filled, ...

    -- We will construct the UPDATE statement using a FROM clause with a subquery/CTE

    -- First, build the list of columns for the CTE select
    -- We need to quote identifiers to be safe
    -- Note: The prompt implies 'row_num' is a column name.

    -- Let's build the dynamic SQL string
    -- UPDATE tbl SET col1 = f.col1_filled, col2 = f.col2_filled ...
    -- FROM (SELECT id, row_num, LAST_VALUE(col1 IGNORE NULLS) OVER (...) as col1_filled, ...) f
    -- WHERE tbl.id = f.id AND tbl.row_num = f.row_num

    -- Build the SET clause parts
    FOR col IN SELECT * FROM unnest(cols_to_fill) LOOP
        set_clause := set_clause || quote_ident(col) || ' = f.' || quote_ident(col) || '_filled, ';
    END LOOP;
    -- Remove trailing comma
    set_clause := rtrim(set_clause, ', ');

    -- Build the CTE select list
    -- We need: id, row_num, and for each col: LAST_VALUE(col IGNORE NULLS) OVER (...) as col_filled
    -- We construct the inner query string
    -- Note: We cannot easily build a CTE with dynamic column aliases in a single string without careful concatenation.
    -- Let's build the inner query string.

    -- Inner query: SELECT id, row_num, LAST_VALUE(col1 IGNORE NULLS) OVER (...) as col1_filled, ...
    -- We need to quote the column names in the SELECT list.

    -- Let's create the inner query string
    -- We'll use a temporary variable to build the select list
    DECLARE
        inner_select text := '';
        col_filled_name text;
    BEGIN
        -- Start with id and row_num
        inner_select := quote_ident(id) || ', ' || quote_ident(row_num);

        FOR col IN SELECT * FROM unnest(cols_to_fill) LOOP
            col_filled_name := col || '_filled';
            inner_select := inner_select || ', LAST_VALUE(' || quote_ident(col) || ' IGNORE NULLS) OVER (' || window_def || ') AS ' || quote_ident(col_filled_name);
        END LOOP;

        -- Now construct the full UPDATE statement
        -- We use a subquery in the FROM clause instead of a CTE for simplicity in dynamic SQL string construction
        -- UPDATE tbl SET ... FROM (SELECT ...) f WHERE ...

        update_sql := 'UPDATE ' || quote_ident(tbl) || ' SET ' || set_clause || 
                      ' FROM (SELECT ' || inner_select || ' FROM ' || quote_ident(tbl) || ') f ' ||
                      ' WHERE ' || quote_ident(tbl) || '.' || quote_ident(id) || ' = f.' || quote_ident(id) || 
                      ' AND ' || quote_ident(tbl) || '.' || quote_ident(row_num) || ' = f.' || quote_ident(row_num);

        EXECUTE update_sql;
    END;
END;
$func$;

