DECLARE
    tmp text[];
    col text;
BEGIN
    SELECT array_agg(column_name)
    INTO tmp
    FROM information_schema.columns
    WHERE table_name = tbl
      AND is_nullable = 'YES';

    FOREACH col IN ARRAY tmp LOOP
        EXECUTE format(
            'UPDATE %I SET %I = (SELECT %I FROM (SELECT %I, ROW_NUMBER() OVER (PARTITION BY %I ORDER BY %I) AS rn FROM %I) AS sub WHERE sub.%I = %I.%I AND sub.rn = (SELECT MIN(rn) FROM (SELECT %I, ROW_NUMBER() OVER (PARTITION BY %I ORDER BY %I) AS rn FROM %I) AS sub2 WHERE sub2.%I = %I.%I AND sub2.%I IS NOT NULL)) WHERE %I IS NULL',
            tbl, col, col, col, id, row_num, tbl, row_num, tbl, row_num, col, id, row_num, tbl, row_num, tbl, row_num, col, col, col
        );
    END LOOP;
END;
