CREATE OR REPLACE FUNCTION f_gap_fill_update(tbl_name text, id_col text, order_col text) 
RETURNS void 
LANGUAGE plpgsql 
AS $func$
DECLARE
    col_name text;
    update_sql text;
    cte_sql text;
    set_clause text;
    columns_to_fill text[];
BEGIN
    -- 1. Identify all nullable columns in the target table, excluding the ID and order columns
    SELECT array_agg(column_name)
    INTO columns_to_fill
    FROM information_schema.columns
    WHERE table_name = tbl_name
      AND is_nullable = 'YES'
      AND column_name NOT IN (id_col, order_col);

    -- If no nullable columns found, exit early
    IF columns_to_fill IS NULL OR array_length(columns_to_fill, 1) = 0 THEN
        RAISE NOTICE 'No nullable columns found to fill in table %', tbl_name;
        RETURN;
    END IF;

    -- 2. Build the CTE part that calculates the forward-filled values
    -- We use LAST_VALUE(col) IGNORE NULLS OVER (PARTITION BY id ORDER BY order_col)
    -- This requires PostgreSQL 15+. For older versions, a different logic is needed.
    cte_sql := 'WITH filled_data AS (';
    cte_sql := cte_sql || 'SELECT ' || id_col || ', ' || order_col || ', ';

    -- Build the select list for the CTE: original_id, original_order, and filled values for each col
    SELECT string_agg(
        'LAST_VALUE(' || col_name || ') IGNORE NULLS OVER (PARTITION BY ' || id_col || ' ORDER BY ' || order_col || ') AS ' || col_name,
        ', '
    )
    INTO set_clause
    FROM unnest(columns_to_fill) AS col_name;

    cte_sql := cte_sql || set_clause;
    cte_sql := cte_sql || ' FROM ' || tbl_name || ')';

    -- 3. Build the UPDATE statement using the CTE
    -- We join the CTE back to the main table on the ID and Order columns
    update_sql := 'UPDATE ' || tbl_name || ' t SET ';

    -- Build the SET clause: col = f.col
    SELECT string_agg(
        't.' || col_name || ' = f.' || col_name,
        ', '
    )
    INTO set_clause
    FROM unnest(columns_to_fill) AS col_name;

    update_sql := update_sql || set_clause;
    update_sql := update_sql || ' FROM filled_data f WHERE t.' || id_col || ' = f.' || id_col || ' AND t.' || order_col || ' = f.' || order_col;

    -- 4. Execute the dynamic SQL
    EXECUTE update_sql;

    RAISE NOTICE 'Forward fill applied to table %', tbl_name;
END;
$func$;

