CREATE OR REPLACE FUNCTION gap_fill_state(s anyelement, v anyelement) 
RETURNS anyelement AS $$
BEGIN
    IF v IS NOT NULL THEN
        RETURN v;
    ELSIF s IS NOT NULL THEN
        RETURN s;
    ELSE
        RETURN NULL;
    END IF;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE AGGREGATE gap_fill(anyelement) (
    SFUNC = gap_fill_state,
    STYPE = anyelement,
    INITCOND = NULL
);

sql:
CREATE OR REPLACE FUNCTION GapFillInternal(s anyelement, v anyelement) RETURNS anyelement AS $$
DECLARE
    temp alias for $0;
BEGIN
    IF v IS NULL AND s IS NOT NULL THEN
        temp := s;
    ELSIF s IS NULL AND v IS NOT NULL THEN
        temp := v;
    ELSIF s IS NOT NULL AND v IS NOT NULL THEN
        temp := v;
    ELSE
        temp := NULL;
    END IF;
    RETURN temp;
END;
$$ LANGUAGE plpgsql;

CREATE AGGREGATE GapFill(anyelement) (
    SFUNC = GapFillInternal,
    STYPE = anyelement
);

SELECT 
