RETURNS jsonb AS $$
DECLARE
    col_list text;
    query_str text;
    final_result jsonb;
BEGIN
    -- Get all column names from 'superhero' ending with '_id'
    SELECT string_agg(column_name, ', ')
    INTO col_list
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'superhero'
      AND column_name LIKE '%_id';

    -- If no columns are found, return an empty array
    IF col_list IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    -- Build the query to select those columns and convert to JSON
    query_str := format('SELECT json_agg(row_to_json(t)) FROM (SELECT %I FROM superhero) t', col_list);

    -- Execute and return
    EXECUTE query_str INTO final_result;

    RETURN final_result;
END;
$$ LANGUAGE plpgsql;

