    SELECT string_agg(column_name, ', ')
    INTO col_list
    FROM information_schema.columns
    WHERE table_name = 'superhero'
      AND column_name LIKE '%_id';

    -- 2. Construct the query to select those columns and convert to JSON
    -- We use row_to_json to convert the row of selected columns into a JSON object
    query := format('SELECT row_to_json(t) FROM (SELECT %I FROM superhero) t', col_list);

    -- 3. Execute the query and return the result
    -- Note: In a real application, you might want to return a set of JSON objects.
    -- Here we execute it to demonstrate the logic. 
    -- If you need to return the data to the client, you would typically use:
    -- EXECUTE query; 
    -- But since DO blocks don't return result sets directly in all clients, 
    -- the following is a pattern to return the JSON array of all rows:

    EXECUTE format('SELECT json_agg(row_to_json(t)) FROM (SELECT %I FROM superhero) t', col_list)
    INTO result;

    -- Output the result (in a psql session, this prints to stdout)
    RAISE NOTICE '%', result;
END $$;

