create or replace function setup_vector_store(table_name text) returns void language plpgsql as $$
declare
    func_name text;
    table_def text;
    func_def text;
begin
    -- Ensure the table name is safe (format with %I handles quoting)

    -- Drop existing table if it exists
    execute format('drop table if exists %I cascade', table_name);

    -- Create the table with the embedding column
    table_def := format(
        'create table %I (
            id bigint primary key generated always as identity,
            description text,
            metadata jsonb,
            embedding vector
        )', table_name
    );
    execute table_def;

    -- Define the name for the search function (e.g., match_my_strategies)
    func_name := format('match_%I', table_name);

    -- Drop the old function if it exists
    execute format('drop function if exists %s(vector, int, jsonb)', func_name);

    -- Create the search function
    func_def := format(
        'create function %s (
            query_embedding vector,
            match_count int default null,
            filter jsonb default ''{{}}''::jsonb
        ) returns table (
            id bigint,
            description text,
            metadata jsonb,
            similarity float
        ) language plpgsql as $$
        begin
            return query
            select 
                id, 
                description, 
                metadata, 
                (embedding <=> query_embedding)::float as similarity
            from %I
            where metadata @> filter
            order by embedding <=> query_embedding
            limit match_count;
        end;$$;',
        func_name, table_name
    );
    execute func_def;
end;
$$;

create or replace function setup_vector_store(table_name text) returns void language plpgsql as $$ 
begin 
  execute 'drop function if exists match_strategies(int, jsonb)'; 
  execute format('create table %I ( id bigint primary key generated always as identity, description text, metadata jsonb, embedding vector )', table_name); 
  execute format('create function match_strategies ( match_count int default null, filter jsonb default ""{}""::jsonb ) returns table ( id bigint, description text, metadata jsonb, similarity float ) language plpgsql as $$ 
    begin 
      return query select id, description, metadata, 1 as similarity from %I where metadata @> filter order by %I.embedding <=> query_embedding limit match_count; 
    end;$$;', table_name, table_name); 
end; 
$$;

