        -- Check if 'gender' key exists and value is 'F'
        IF _info_jsonb ? 'gender' AND (_info_jsonb ->> 'gender') = 'F' THEN
            _info_jsonb := jsonb_set(_info_jsonb, '{gender}', '"M"'::jsonb);
            _output_info := _info_jsonb::text;
        END IF;
    EXCEPTION WHEN others THEN
        -- If JSON is invalid or any other error, keep original _info
        _output_info := _info;
    END;

    -- Create temp table if not exists
    CREATE TEMP TABLE IF NOT EXISTS _json_update_result (info TEXT) ON COMMIT DROP;

    -- Clear and insert result
