CREATE TABLE "BusinessCategories"( 
    "ID" INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, 
    "BusinessCategoryID" INT NOT NULL
);

ALTER TABLE "BusinessCategories" 
ADD CONSTRAINT fk_business_category 
FOREIGN KEY ("BusinessCategoryID") 
REFERENCES "EventCategories"("ID");

CREATE OR REPLACE FUNCTION check_business_category_flag()
RETURNS TRIGGER AS $$
BEGIN
    IF EXISTS (
        SELECT 1 
        FROM "EventCategories" 
        WHERE "ID" = NEW."BusinessCategoryID" 
        AND "IsBusinessCategory" IS NOT TRUE
    ) THEN
        RAISE EXCEPTION 'Cannot reference EventCategory with IsBusinessCategory = false or null';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER enforce_business_category_flag
BEFORE INSERT OR UPDATE ON "BusinessCategories"
FOR EACH ROW
EXECUTE FUNCTION check_business_category_flag();

