stage1_sql:
DO $$
DECLARE
    batch_size INT := 10000;
    rows_inserted INT;
BEGIN
    LOOP
        -- Insert only players that don't already exist in player_stats
        INSERT INTO player_stats (player_id, match_id, goals, assists, yellow_cards, red_cards, minutes_played)
        SELECT pst.player_id, pst.match_id, pst.goals, pst.assists, pst.yellow_cards, pst.red_cards, pst.minutes_played
        FROM player_stats_temp pst
        WHERE NOT EXISTS (
            SELECT 1 FROM player_stats ps WHERE ps.player_id = pst.player_id
        )
        LIMIT batch_size;

        -- Get the number of rows inserted
        GET DIAGNOSTICS rows_inserted = ROW_COUNT;

        -- Exit loop if no more rows were inserted
        EXIT WHEN rows_inserted = 0;

        -- Optional: Reduce batch size if needed (not strictly necessary here)
        -- batch_size := GREATEST(1, batch_size / 2);
    END LOOP;
END $$;

